<?php require_once 'config.php'; require_login(); $no=$_GET['token']??''; $s=$conn->prepare('SELECT * FROM tokens WHERE token_no=?');$s->bind_param('s',$no);$s->execute();$t=$s->get_result()->fetch_assoc();if(!$t){http_response_code(404);exit('Token not found');}
$uid=(int)($_SESSION['user']['id']??0);
if(role()==='passenger' && (int)$t['user_id']!==$uid){http_response_code(403);exit('You are not allowed to download this token.');} $file=tempnam(sys_get_temp_dir(),'rpta_').'.pdf'; require_once __DIR__.'/lib_pdf.php'; make_token_pdf($file,$t); if(!is_file($file)){http_response_code(500);exit('PDF generation failed');} header('Content-Type: application/pdf');$disp = isset($_GET['download']) ? 'attachment' : 'inline'; header('Content-Disposition: '.$disp.'; filename="'.preg_replace('/[^A-Za-z0-9_-]/','_',$no).'.pdf"');header('Content-Length: '.filesize($file));header('Cache-Control: private, max-age=0, must-revalidate');readfile($file);@unlink($file);exit; ?>